/*
 * Removing is for drafts and mistakes. Hand-ins, messages and check-in answers point at a
 * step by its id, so a step with any of them stays: the coach unshares it instead, and the
 * learner's work is never left pointing at nothing. Library files are never deleted here
 * either: copies in other plans may name them (DECISIONS, DBU-03).
 * A check-in sent "N days after" the removed step keeps the day it had and loses the rule
 * (DBU-10): it is then sent on that date, which the coach can change.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const q = (c, where, limit) => R.query(c, where, { limit: limit || 1000, plain: true });
    const id = String(Inputs.stepId || '');
    const found = id ? await q('Step', { objectId: { equalTo: id } }, 2) : [];
    if (found.length !== 1) return refuse('That step is no longer in the plan. Reload the page.');
    const step = found[0];
    for (const [table, what] of [['Submission', 'handed work in for it'], ['Message', 'written about it'], ['CheckinResponse', 'answered it']]) {
      if ((await q(table, { step: { equalTo: id } }, 1)).length) {
        return refuse('“' + step.title + '” stays: the learner has ' + what + '. Unshare it instead if they should not see it.');
      }
    }
    await R.delete(id, { className: 'Step' });
    const rest = (await q('Step', { plan: { equalTo: step.plan } }))
      .sort((a, b) => (a.position - b.position) || String(a.objectId).localeCompare(String(b.objectId)));
    for (let i = 0; i < rest.length; i++) {
      const change = {};
      if (rest[i].position !== i + 1) change.position = i + 1;
      if (rest[i].sendAfter && rest[i].sendAfter.step === id) change.sendAfter = null;
      if (Object.keys(change).length) await R.save(rest[i].objectId, change, { className: 'Step' });
    }
    if (step.shared === true) {
      await R.create('Doorbell', { learner: step.learner, topic: 'plan' }, { acl: { [step.learner]: { read: true }, 'role:staff': { read: true } } });
    }
    Outputs.title = step.title;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:removeStep]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
